import{_ as e,c as a,o as t,a2 as i}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"Create Database","description":"","frontmatter":{},"headers":[],"relativePath":"guide/console/setup/create-database.md","filePath":"guide/console/setup/create-database.md","lastUpdated":1778363927000}'),o={name:"guide/console/setup/create-database.md"},l=i('<h1 id="create-database" tabindex="-1">Create Database <a class="header-anchor" href="#create-database" aria-label="Permalink to &quot;Create Database&quot;">​</a></h1><blockquote><p>Create the database if it does not exist.</p></blockquote><h2 id="command-information" tabindex="-1">Command Information <a class="header-anchor" href="#command-information" aria-label="Permalink to &quot;Command Information&quot;">​</a></h2><ul><li><strong>Signature:</strong> <code>modularous:create:database [--connection[=CONNECTION]]</code></li><li><strong>Category:</strong> Setup</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="create-the-default-database" tabindex="-1">Create the default database <a class="header-anchor" href="#create-the-default-database" aria-label="Permalink to &quot;Create the default database&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:create:database</span></span></code></pre></div><h3 id="create-a-database-on-a-specific-connection" tabindex="-1">Create a database on a specific connection <a class="header-anchor" href="#create-a-database-on-a-specific-connection" aria-label="Permalink to &quot;Create a database on a specific connection&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:create:database</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --connection=mysql</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:create:database</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --connection=pgsql</span></span></code></pre></div><h2 id="modularous-create-database" tabindex="-1"><code>modularous:create:database</code> <a class="header-anchor" href="#modularous-create-database" aria-label="Permalink to &quot;`modularous:create:database`&quot;">​</a></h2><p>Creates the database defined in the given connection config if it does not already exist. The database name, host, port, charset, and collation are all read from <code>config(&#39;database.connections.&lt;connection&gt;&#39;)</code>. Useful in CI pipelines and initial setup scripts where the database may not yet exist.</p><p><strong>Supported drivers:</strong></p><table><thead><tr><th>Driver</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>mysql</code></td><td>Runs <code>CREATE DATABASE IF NOT EXISTS</code> with charset and collation from config (defaults: <code>utf8mb4</code> / <code>utf8mb4_unicode_ci</code>)</td></tr><tr><td><code>pgsql</code></td><td>Creates the database if it does not appear in <code>pg_database</code></td></tr><tr><td><code>sqlite</code></td><td>Touches the file at the configured path, creating parent directories as needed</td></tr><tr><td><code>sqlsrv</code></td><td>Runs <code>CREATE DATABASE</code> if the name is not in <code>sys.databases</code></td></tr></tbody></table><h3 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h3><ul><li><code>modularous:create:database [--connection[=CONNECTION]]</code></li></ul><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><h4 id="connection" tabindex="-1"><code>--connection</code> <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;`--connection`&quot;">​</a></h4><p>The database connection to use. Reads from <code>config(&#39;database.default&#39;)</code> when omitted.</p><ul><li>Accept value: yes</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>NULL</code></li></ul><h4 id="help-h" tabindex="-1"><code>--help|-h</code> <a class="header-anchor" href="#help-h" aria-label="Permalink to &quot;`--help|-h`&quot;">​</a></h4><p>Display help for the given command. When no command is given display help for the list command</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>false</code></li></ul><h4 id="quiet-q" tabindex="-1"><code>--quiet|-q</code> <a class="header-anchor" href="#quiet-q" aria-label="Permalink to &quot;`--quiet|-q`&quot;">​</a></h4><p>Do not output any message</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>false</code></li></ul><h4 id="verbose-v-vv-vvv" tabindex="-1"><code>--verbose|-v|-vv|-vvv</code> <a class="header-anchor" href="#verbose-v-vv-vvv" aria-label="Permalink to &quot;`--verbose|-v|-vv|-vvv`&quot;">​</a></h4><p>Increase the verbosity of messages: 1 for normal output, 2 for more verbose output and 3 for debug</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>false</code></li></ul><h4 id="version-v" tabindex="-1"><code>--version|-V</code> <a class="header-anchor" href="#version-v" aria-label="Permalink to &quot;`--version|-V`&quot;">​</a></h4><p>Display this application version</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>false</code></li></ul><h4 id="ansi-no-ansi" tabindex="-1"><code>--ansi|--no-ansi</code> <a class="header-anchor" href="#ansi-no-ansi" aria-label="Permalink to &quot;`--ansi|--no-ansi`&quot;">​</a></h4><p>Force (or disable --no-ansi) ANSI output</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: yes</li><li>Default: <code>NULL</code></li></ul><h4 id="no-interaction-n" tabindex="-1"><code>--no-interaction|-n</code> <a class="header-anchor" href="#no-interaction-n" aria-label="Permalink to &quot;`--no-interaction|-n`&quot;">​</a></h4><p>Do not ask any interactive question</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>false</code></li></ul><h4 id="env" tabindex="-1"><code>--env</code> <a class="header-anchor" href="#env" aria-label="Permalink to &quot;`--env`&quot;">​</a></h4><p>The environment the command should run under</p><ul><li>Accept value: yes</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>NULL</code></li></ul>',40),s=[l];function n(d,r,c,h,u,p){return t(),a("div",null,s)}const v=e(o,[["render",n]]);export{m as __pageData,v as default};
